@startuml

class Bookmaker {}

class Bettor {
  + name : string
  + id : int
}

class Race {
  + raceId : int
  + raceName : string
}

class Runner {
  + runnerId : int
  + horseName : string
}

class Jockey {
  + name : string
  + licenseNumber : string
}

class Bet {
  + amount : double
  + odds : double
}

Bookmaker "1" -- "*" Bettor
Bettor "1" -- "*" Bet
Race "1" *-- "1..*" Runner
Runner "1" -- "1" Jockey
Race "1" -- "1" Runner : winner
Bet "*" -- "1" Race
Bet "*" -- "1" Runner

@enduml

